function httpPost(url, headers, body) {
  return new Promise((resolve) => {
    try {
      const u = new URL(url);
      const opts = { hostname: u.hostname, path: u.pathname, method: 'POST', headers: { ...headers, 'Content-Type': 'application/json' } };
      const req = https.request(opts, res => { let data = ''; res.on('data', c => data += c); res.on('end', () => { try { resolve(JSON.parse(data)); } catch { resolve({}); } }); });
      req.on('error', () => resolve({})); req.setTimeout(15000, () => { req.destroy(); resolve({}); });
      req.write(JSON.stringify(body)); req.end();
    } catch { resolve({}); }
  });
}
