function escapeLatexText(input) {
  if (typeof input !== 'string') return '';
  return input.replace(/\\/g, '\\textbackslash{}').replace(/&/g, '\\&').replace(/%/g, '\\%').replace(/\$/g, '\\$').replace(/#/g, '\\#').replace(/_/g, '\\_').replace(/\{/g, '\\{').replace(/\}/g, '\\}').replace(/\^/g, '\\textasciicircum{}').replace(/~/g, '\\textasciitilde{}');
}
function cleanText(str) {
  if (!str) return '';
  return str.replace(/\\[a-zA-Z]+\{([^}]*)\}/g, '$1').replace(/\\[a-zA-Z]+/g, '').replace(/\$[^$]*\$/g, '').trim();
}
function wrapResumeWithSkeleton(params) {
  const { skeleton, headerLatex, contentLatex } = params;
  if (!skeleton) return '\\documentclass[letterpaper,11pt]{article}\n\\begin{document}\n' + headerLatex + '\n\n' + contentLatex + '\n\\end{document}\n';
  const lines = skeleton.replace(/\r\n/g, '\n').split('\n');
  const hs = lines.findIndex(l => l.trim() === '%%% HEADER_START');
  const he = lines.findIndex((l, i) => i > hs && l.trim() === '%%% HEADER_END');
  if (hs !== -1 && he !== -1) lines.splice(hs + 1, he - hs - 1, headerLatex.trim());
  const cs = lines.findIndex(l => l.trim() === '%%% CONTENT_START');
  const ce = lines.findIndex((l, i) => i > cs && l.trim() === '%%% CONTENT_END');
  if (cs !== -1 && ce !== -1) { lines.splice(cs + 1, ce - cs - 1, contentLatex.trim()); return lines.join('\n'); }
  const endDocIdx = lines.findIndex(l => l.includes('\\end{document}'));
  if (endDocIdx !== -1) lines.splice(endDocIdx, 0, contentLatex.trim());
  else lines.push(contentLatex.trim());
  return lines.join('\n');
}
function normalizeLatexForPdflatex(input) {
  if (!input) return input;
  let s = input.replace(/\r\n/g, '\n');
  s = s.replace(/[\u201C\u201D]/g, '"').replace(/[\u2018\u2019]/g, "'").replace(/\u2026/g, '...').replace(/[\u2013\u2014]/g, '--').replace(/\u00A0/g, ' ');
  s = s.replace(/\u20B9/g, 'INR ').replace(/\u20AC/g, 'EUR ').replace(/\u00A3/g, 'GBP ').replace(/(?<!\\)\$/g, '\\$');
  s = s.replace(/[^\x09\x0A\x0D\x20-\x7E]/g, '');
  return s;
}
const ctx = $('Load Revise Context').item.json;
const reviseType = ctx.last_apply.revise_type;
const revisedJson = $input.first().json.output || {};
const personal = ctx.last_apply.personal || {};
if (reviseType === 'cover') {
  const contentLines = [];
  contentLines.push('\\begin{lettercontent}');
  contentLines.push('\\begin{center}');
  contentLines.push('{\\large\\textbf{' + escapeLatexText(revisedJson.title || '') + '}}');
  contentLines.push('\\end{center}\n\\vspace{4mm}\n');
  contentLines.push(escapeLatexText(revisedJson.salutation || 'Dear Hiring Team,'));
  contentLines.push('');
  contentLines.push(escapeLatexText(revisedJson.hook || ''));
  contentLines.push('');
  contentLines.push('\\begin{itemize}[leftmargin=0.2in]');
  for (const bullet of (revisedJson.bullets || [])) {
    contentLines.push('  \\item \\textbf{' + escapeLatexText(cleanText(bullet.keyword || '')) + ':} ' + escapeLatexText(cleanText(bullet.text || '')));
  }
  contentLines.push('\\end{itemize}\n');
  contentLines.push(escapeLatexText(revisedJson.cta || ''));
  contentLines.push('\\end{lettercontent}');
  let fullLatex = wrapResumeWithSkeleton({ skeleton: ctx.cover_skeleton, headerLatex: '% Header omitted', contentLatex: contentLines.join('\n') });
  fullLatex = fullLatex.replace('{{NAME}}', escapeLatexText(personal.name || '')).replace('{{PHONE}}', escapeLatexText(personal.phone_display || personal.phone_primary || '')).replace('{{EMAIL}}', personal.email || '').replace('{{LINKEDIN}}', personal.linkedin || '');
  return [{ json: { latex: normalizeLatexForPdflatex(fullLatex), chat_id: ctx.chat_id, job_title: ctx.last_apply.job_title, company: ctx.last_apply.company, revise_type: 'cover', changes_summary: revisedJson.changes_summary || '' } }];
} else {
  const skeleton = ctx.last_apply.resume_skeleton;
  const headerTemplate = (() => { const lines = (skeleton || '').replace(/\r\n/g, '\n').split('\n'); const si = lines.findIndex(l => l.trim() === '%%% HEADER_START'); if (si === -1) return ''; const ei = lines.findIndex((l, i) => i > si && l.trim() === '%%% HEADER_END'); if (ei === -1) return ''; return lines.slice(si + 1, ei).join('\n').trim(); })();
  const headerLatex = headerTemplate.replace('{{NAME}}', escapeLatexText(personal.name || '')).replace('{{PHONE}}', escapeLatexText(personal.phone_display || personal.phone_primary || '')).replace('{{EMAIL}}', personal.email || '').replace('{{LINKEDIN}}', personal.linkedin || '').replace('{{PORTFOLIO_LINE}}', '').replace('{{GITHUB_LINE}}', '').replace('{{LOCATION_LINE}}', '');
  const sections = revisedJson.sections || [];
  const contentParts = [];
  for (const section of sections) {
