      contentParts.push('\\resumeSubHeadingListEnd');
    } else if (heading === 'Experience') {
      contentParts.push('\\section{Experience}\n\\resumeSubHeadingListStart');
      for (const item of items) {
        if (item.type === 'role') {
          contentParts.push('  \\resumeSubheading{' + escapeLatexText(item.role || '') + '}{' + escapeLatexText(item.dates || '') + '}{' + escapeLatexText(item.company || '') + '}{' + escapeLatexText(item.location || '') + '}');
          if (item.bullets && item.bullets.length > 0) { contentParts.push('  \\resumeItemListStart'); for (const b of item.bullets) { const kw = b.keyword ? '\\textbf{' + escapeLatexText(cleanText(b.keyword)) + ':} ' : ''; contentParts.push('    \\resumeItem{' + kw + escapeLatexText(cleanText(b.text || '')) + '}'); } contentParts.push('  \\resumeItemListEnd'); }
        }
      }
      contentParts.push('\\resumeSubHeadingListEnd');
    } else if (heading === 'Projects') {
      contentParts.push('\\section{Projects}\n\\resumeSubHeadingListStart');
      for (const item of items) {
        if (item.type === 'project') {
          contentParts.push('  \\resumeProjectHeading{\\textbf{' + escapeLatexText(item.name || '') + '}' + (item.tech ? ' $|$ ' + escapeLatexText(item.tech) : '') + '}{' + (item.url ? escapeLatexText(item.url) : '') + '}');
          if (item.bullets && item.bullets.length > 0) { contentParts.push('  \\resumeItemListStart'); for (const b of item.bullets) { const kw = b.keyword ? '\\textbf{' + escapeLatexText(cleanText(b.keyword)) + ':} ' : ''; contentParts.push('    \\resumeItem{' + kw + escapeLatexText(cleanText(b.text || '')) + '}'); } contentParts.push('  \\resumeItemListEnd'); }
        }
      }
      contentParts.push('\\resumeSubHeadingListEnd');
    }
  }
  const fullLatex = wrapResumeWithSkeleton({ skeleton, headerLatex, contentLatex: contentParts.join('\n') });
  return [{ json: { latex: normalizeLatexForPdflatex(fullLatex), chat_id: ctx.chat_id, job_title: ctx.last_apply.job_title, company: ctx.last_apply.company, revise_type: 'resume', changes_summary: revisedJson.changes_summary || '' } }];
}

