const sd = $getWorkflowStaticData('global');
const resumeForgeOutput = $('ResumeForge').first().json.output || {};
const forgeScoreOutput = $('ForgeScore').first().json.output || {};
const seniorityOutput = $('SeniorityDetector').first().json.output || {};
const jdCtx = $('Prepare Job Context').first().json;
sd.last_resume_json = resumeForgeOutput.sections || resumeForgeOutput || {};
sd.last_jd = jdCtx.job_description || '';
sd.last_fit_strategy = seniorityOutput.fit_strategy || 'perfect_fit';
sd.last_keyword_gaps = forgeScoreOutput.keyword_gaps || [];
return $input.all();

// Build You.com Queries — reads explicitly from Parse Expand Query
// Credential handled by the native You.com node — no env check needed.

const ctx = $('Parse Expand Query').first().json;
const queries = ctx.youcom_queries || [];

if (!queries.length) {
  // Fallback: build from role_families if youcom_queries missing (schema v1 compat)
  const roles = ctx.role_families || [];
  if (!roles.length) {
    return [{ json: { _disabled: true, source: 'youcom', reason: 'No queries' } }];
  }
  const top = roles.slice(0, 3);
  const loc = ctx.location_canonical || '';
  const locPart = loc ? ' "' + loc.split(',')[0] + '"' : '';
  return [
    { json: { _disabled: false, query: 'site:myworkdayjobs.com "' + top[0] + '"' + locPart } },
    { json: { _disabled: false, query: 'site:jobs.ashbyhq.com "' + top[0] + '"' + locPart } },
    { json: { _disabled: false, query: '(site:boards.greenhouse.io OR site:jobs.lever.co) "' + top[0] + '"' + locPart } },
  ];
}

return queries.map(q => ({ json: { _disabled: false, query: q } }));

// Normalize You.com Search output → standard job object
// Native node shape: { results: { web: [...], snippets: [...] } }

const hits = $input.all();
const allJobs = [];

function extractCompanyFromUrl(url) {
  let m;
  if ((m = url.match(/(?:boards|job-boards)\.greenhouse\.io\/(?:embed\/job_board\?for=)?([^/?&#]+)/))) return m[1];
  if ((m = url.match(/jobs\.lever\.co\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/jobs\.ashbyhq\.com\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/([^.\/]+)\.wd\d+\.myworkdayjobs\.com/))) return m[1];
  if ((m = url.match(/apply\.workable\.com\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/jobs\.smartrecruiters\.com\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/workatastartup\.com\/jobs\/\d+\/[^?#]*?-at-([^/?#]+)/))) return m[1];
  if ((m = url.match(/wellfound\.com\/jobs\/[^/]*?-at-([^/?#]+)/))) return m[1];
  if ((m = url.match(/wellfound\.com\/company\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/(?:weworkremotely|remoteok|himalayas|remotive|jobicy|arbeitnow)\./))) return url.match(/(?:weworkremotely|remoteok|himalayas|remotive|jobicy|arbeitnow)/)[0];
  if ((m = url.match(/^https?:\/\/(?:www\.)?([^.]+)\./))) return m[1];
  return 'unknown';
}

function extractLocationFromText(text) {
  let m;
  if ((m = text.match(/(?:in|at|–|-|·|—)\s*([A-Z][\w\s]+,\s*[A-Z]{2,})/))) return m[1].trim();
  if ((m = text.match(/\b(New York|San Francisco|Seattle|Boston|Austin|Chicago|Los Angeles|Remote)\b/i))) return m[1];
  return '';
}

for (const item of hits) {
  if (item.json._disabled) continue;

  const results = item.json.results;
  let entries = [];
  if (Array.isArray(results)) entries = results;
  else if (results && Array.isArray(results.web)) entries = results.web;
  else if (Array.isArray(item.json.hits)) entries = item.json.hits;
  else if (Array.isArray(item.json.organic)) entries = item.json.organic;
  else if (Array.isArray(item.json.web)) entries = item.json.web;

  for (const r of entries) {
    const url = r.url || r.link || '';
    if (!url) continue;
    const title = r.title || '';
    const desc = r.description || r.snippet || (r.snippets || []).join(' ') || '';
    const company = extractCompanyFromUrl(url);
    const location = extractLocationFromText(title) || extractLocationFromText(desc) || '';

    allJobs.push({
      job_id: `youcom-${company}-${allJobs.length}`,
      title,
      company,
      location,
      department: '',
      url,
      description_snippet: desc.substring(0, 500),
      updated_at: r.page_age || r.published_date || '',
      source: 'youcom'
    });
  }
}

return [{ json: { jobs: allJobs, source: 'youcom', count: allJobs.length } }];

// Build Serper Queries — reads explicitly from Parse Expand Query
// Credential handled by the Serper Header Auth on the HTTP Request node.

const ctx = $('Parse Expand Query').first().json;
const queries = ctx.serper_queries || [];

if (!queries.length) {
  // Fallback: build from role_families if serper_queries missing
  const roles = ctx.role_families || [];
  if (!roles.length) {
    return [{ json: { _disabled: true, source: 'serper', reason: 'No queries and no role_families' } }];
  }
  const top = roles.slice(0, 2);
  const yesterday = new Date(Date.now() - 24*60*60*1000).toISOString().split('T')[0];
  const loc = ctx.location_canonical || '';
  const locPart = loc ? ' "' + loc.split(',')[0] + '"' : '';
  return [
    { json: { _disabled: false, query: '(site:boards.greenhouse.io OR site:jobs.lever.co) "' + top[0] + '" after:' + yesterday + locPart } },
    { json: { _disabled: false, query: '(site:jobs.ashbyhq.com OR site:myworkdayjobs.com) "' + top[0] + '" after:' + yesterday + locPart } },
  ];
}

return queries.map(q => ({ json: { _disabled: false, query: q } }));

const hits = $input.all();
const allJobs = [];

for (const item of hits) {
  const results = item.json.organic || [];  // Serper-specific
  for (const r of results) {
    const url = r.link || '';              // Serper-specific
    if (!url) continue;
    let company = 'unknown', m;
    if ((m = url.match(/([^.]+)\.wd\d+\.myworkdayjobs\.com/))) company = m[1];
    else if ((m = url.match(/boards\.greenhouse\.io\/([^/?]+)/))) company = m[1];
    else if ((m = url.match(/jobs\.lever\.co\/([^/?]+)/))) company = m[1];
    else if ((m = url.match(/jobs\.ashbyhq\.com\/([^/?]+)/))) company = m[1];
    else if ((m = url.match(/apply\.workable\.com\/([^/?]+)/))) company = m[1];
    else if ((m = url.match(/jobs\.smartrecruiters\.com\/([^/?]+)/))) company = m[1];
    allJobs.push({
      job_id: `serper-${company}-${allJobs.length}`,  // serper prefix
      title: r.title || '',
      company,
      location: '',
      department: '',
      url,
      description_snippet: (r.snippet || '').substring(0, 500),  // Serper-specific
      updated_at: r.date || '',                                    // Serper-specific
      source: 'serper'                                             // serper source
    });
  }
}

return [{ json: { jobs: allJobs, source: 'serper', count: allJobs.length } }];

// Build FC Queries — outputs body as a real object for Custom Body Mode
const ctx = $('Parse Expand Query').first().json;
const queries = ctx.firecrawl_queries || [];
if (!queries.length) {
  return [{ json: { _disabled: true, source: 'firecrawl', reason: 'No firecrawl_queries in intent output' } }];
}

const standardATS = [
  'boards.greenhouse.io', 'job-boards.greenhouse.io', 'jobs.lever.co',
  'jobs.ashbyhq.com', 'apply.workable.com', 'myworkdayjobs.com',
  'jobs.smartrecruiters.com', 'workatastartup.com'
];
const remoteAggregators = [
  'weworkremotely.com', 'remoteok.com', 'himalayas.app',
  'remotive.com', 'jobicy.com', 'wellfound.com', 'arbeitnow.com'
];

const remoteOnly = ctx.remote_preference === 'remote_only';
const includeDomains = remoteOnly
  ? [...standardATS, ...remoteAggregators]
  : standardATS;
const limit = remoteOnly ? 25 : 10;

const location  = ctx.location_canonical || null;
const country   = ctx.country || 'US';
const freshness = ctx.freshness || 'qdr:w';

return queries.slice(0, 4).map(query => ({
  json: {
    _disabled: false,
    query,
    // bodyObj is the actual object passed to Custom Body (not stringified)
    bodyObj: {
      query,
      limit,
      includeDomains,
      tbs: freshness,
      ignoreInvalidURLs: true,
      country,
      ...(location ? { location } : {})
    }
  }
}));

// Normalize Firecrawl Search results → standard job object
// Native node shape: { success, data: { web: [...], news: [...], images: [...] } }

const hits = $input.all();
const allJobs = [];

function extractCompanyFromUrl(url) {
  let m;
  if ((m = url.match(/(?:boards|job-boards)\.greenhouse\.io\/(?:embed\/job_board\?for=)?([^/?&#]+)/))) return m[1];
  if ((m = url.match(/jobs\.lever\.co\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/jobs\.ashbyhq\.com\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/([^.\/]+)\.wd\d+\.myworkdayjobs\.com/))) return m[1];
  if ((m = url.match(/apply\.workable\.com\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/jobs\.smartrecruiters\.com\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/workatastartup\.com\/jobs\/\d+\/[^?#]*?-at-([^/?#]+)/))) return m[1];
  if ((m = url.match(/wellfound\.com\/jobs\/[^/]*?-at-([^/?#]+)/))) return m[1];
  if ((m = url.match(/wellfound\.com\/company\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/(?:weworkremotely|remoteok|himalayas|remotive|jobicy|arbeitnow)\./))) return url.match(/(?:weworkremotely|remoteok|himalayas|remotive|jobicy|arbeitnow)/)[0];
  if ((m = url.match(/^https?:\/\/(?:www\.)?([^.]+)\./))) return m[1];
  return 'unknown';
}

function extractLocationFromTitle(title) {
  // Pull common location patterns out of titles like "ML Engineer - New York, NY"
  let m;
  if ((m = title.match(/(?:in|at|–|-|·|—)\s*([A-Z][\w\s]+,\s*[A-Z]{2,})/))) return m[1].trim();
  if ((m = title.match(/(?:in|at|–|-|·|—)\s*(New York|San Francisco|Seattle|Boston|Austin|Chicago|Los Angeles|Remote)/i))) return m[1];
  return '';
}

for (const item of hits) {
  if (item.json._disabled) continue;

  const data = item.json.data;
  let results = [];
  if (Array.isArray(data)) results = data;
  else if (data && Array.isArray(data.web)) results = data.web;
  else if (Array.isArray(item.json.results)) results = item.json.results;
  else if (Array.isArray(item.json.web)) results = item.json.web;

  for (const r of results) {
    const url = r.url || r.metadata?.sourceURL || '';
    if (!url) continue;
    const title = r.title || r.metadata?.title || '';
    const company = extractCompanyFromUrl(url);
    const location = r.metadata?.location || r.location || extractLocationFromTitle(title) || '';

    allJobs.push({
      job_id: 'fc-' + company + '-' + allJobs.length,
      title,
      company,
      location,
      department: '',
      url,
      description_snippet: (r.description || r.markdown || r.metadata?.description || '').substring(0, 600),
      updated_at: r.metadata?.publishedTime || r.publishedTime || '',
      source: 'firecrawl'
    });
  }
}

return [{ json: { jobs: allJobs, source: 'firecrawl', count: allJobs.length } }];

// Pre-flight: Providers
// Firecrawl uses n8n credentials — no env var needed.
// You.com and Serper still use env vars.

const ctx = $input.first().json;
const active = [];

// Firecrawl: always active (credential stored in node)
active.push('Firecrawl 🔥');
// You.com: still uses env var
if ($env.YOUCOM_API_KEY) active.push('You.com 🔍');
// Serper: still uses env var
if ($env.SERPER_API_KEY) active.push('Serper ⚡');

// active.length is always >= 1 (Firecrawl), so the IF: Providers?
// gate that checks _no_providers === true will never fire.
// Keeping the structure in case user removes Firecrawl credential.

return [{ json: {
  ...ctx,
  _providers_active: active,
  _providers_count: active.length,
  _no_providers: false
}}];

// Render user prefs as a human-readable Telegram message.
const sd = $getWorkflowStaticData("global");
const prefs = sd.user_prefs || {};
const skip = ["_schema_version", "_history", "_updated_at"];
const entries = Object.entries(prefs).filter(([k]) => !skip.includes(k));

if (!entries.length) {
  return [{ json: { message: "ℹ️ No preferences set yet. I'll remember things as you tell me.\n\nTry: \"remember I'm in NYC\" or \"set min salary to $150k\" or \"send me jobs at 9am and 5pm\"" } }];
}

// Pretty-render schedule_times if present
const renderSchedule = (times, tz) => {
  if (!Array.isArray(times)) return null;
  if (times.length === 0) return "_scheduled searches disabled_";
  const tzShort = (tz || "America/New_York").split("/").pop().replace(/_/g, " ");
  return `Daily at ${times.join(", ")} (${tzShort})`;
};

const lines = [];
const tz = prefs.timezone;
for (const [k, v] of entries) {
  if (k === "timezone") continue;                         // shown alongside schedule
  if (k === "schedule_times") {
    const rendered = renderSchedule(v, tz);
    lines.push(`• *schedule:* ${rendered}`);
    continue;
  }
  lines.push(`• *${k}:* ${JSON.stringify(v)}`);
}

const updatedAt = prefs._updated_at
  ? `\n\n_Last updated: ${new Date(prefs._updated_at).toLocaleDateString()}_`
  : "";

return [{ json: { message: `📋 *Your preferences:*\n\n${lines.join("\n")}${updatedAt}` } }];

// Handle Prefs Update v3
// Regex-based preference extractor. Schedule times rounded to 3-hour boundary
// to match the every-3-hours Schedule Tick cron.

const msg = ($('Extract Input').first().json.message_text || '').toLowerCase();
const sd  = $getWorkflowStaticData('global');
if (!sd.user_prefs) sd.user_prefs = { _schema_version: 1, _history: [] };
const prefs = sd.user_prefs;
const changes = [];
const delta   = {};
let m;

// ── Location ──────────────────────────────────────────────────────────────
if ((m = msg.match(/(?:i['\u2019]?m (?:based |located )?in|location[:\s]+|moved? to|set location (?:to )?)\s*([\w\s,]+?)(?:\s*$|[.,!?])/))) {
  const loc = m[1].trim();
  if (loc.length > 2) delta.location_canonical = loc;
}

// ── Remote ────────────────────────────────────────────────────────────────
if (/always remote|remote only|remote-only/.test(msg))           delta.remote_preference = 'remote_only';
else if (/hybrid(?:\s+ok)?|open to hybrid/.test(msg))           delta.remote_preference = 'hybrid_ok';
else if (/in.?office only|no remote/.test(msg))                  delta.remote_preference = 'in_office_only';

// ── Visa ──────────────────────────────────────────────────────────────────
const visaSigs = [];
if (/cap.?exempt/.test(msg))            visaSigs.push('cap-exempt');
if (/h1b|h-1b/.test(msg))               visaSigs.push('h1b');
if (/sponsorship|sponsor/.test(msg))    visaSigs.push('sponsorship');
if (visaSigs.length) delta.visa_signals = visaSigs;

// ── Salary ────────────────────────────────────────────────────────────────
if ((m = msg.match(/(?:min(?:imum)? salary|at least|salary[:\s]+|above|over)\s*\$?([\d]+(?:k|,\d{3})?)/))) {
  delta.salary_signals = ['$' + m[1]];
}

// ── Seniority ────────────────────────────────────────────────────────────
if (/\bsenior\b|\bstaff\b|\bprincipal\b/.test(msg))        delta.seniority = 'senior';
else if (/mid.?level|mid level/.test(msg))                       delta.seniority = 'mid';
else if (/junior|entry.?level|new grad/.test(msg))               delta.seniority = 'junior';

// ── Verbose ───────────────────────────────────────────────────────────────
if (/verbose on/.test(msg))  delta.verbose = true;
if (/verbose off/.test(msg)) delta.verbose = false;

// ── Max YOE ───────────────────────────────────────────────────────────────
if ((m = msg.match(/(?:max(?:imum)?|less than|under|at most)\s*(\d+)\s*(?:years?|yrs?|yoe)/))) {
  delta.max_yoe = parseInt(m[1], 10);
}

// ── Freshness ────────────────────────────────────────────────────────────
if (/past day|last 24|qdr:d|daily/.test(msg))                    delta.freshness = 'qdr:d';
else if (/past week|last week|qdr:w/.test(msg))                  delta.freshness = 'qdr:w';
else if (/past month|last month|qdr:m/.test(msg))                delta.freshness = 'qdr:m';

// ── Schedule times (rounded to 3-hour boundary) ──────────────────────────
const schedCtx   = /schedul[a-z]*|digest|every (?:morning|day|weekday|evening|afternoon)|send (?:me )?(?:jobs|searches)|run at|fire at|jobs at/i;
const disableCtx = /stop|disable|pause|turn off|no more|halt|cancel/i;

if (schedCtx.test(msg)) {
  if (disableCtx.test(msg)) {
    delta.schedule_times = [];
  } else {
    const timeRe = /\b(\d{1,2})(?::(\d{2}))?\s*(am|pm|a\.m\.|p\.m\.)?\b/gi;
    const found  = new Set();
    let tm;
    while ((tm = timeRe.exec(msg)) !== null) {
      let hr = parseInt(tm[1], 10);
      const mn = tm[2] ? parseInt(tm[2], 10) : 0;
      const mer = tm[3] ? tm[3].toLowerCase().replace(/\./g,'') : null;
      if (hr > 23) continue;
      if (!mer) {
        if (hr >= 1 && hr <= 7) hr += 12;
        else if (hr === 0) continue;
      } else {
        if (mer === 'pm' && hr < 12) hr += 12;
        if (mer === 'am' && hr === 12) hr = 0;
      }
      // Round to nearest 3-hour boundary (00, 03, 06, 09, 12, 15, 18, 21)
      const total   = hr * 60 + mn;
      const rounded = Math.round(total / 180) * 180;
      const rh = String(Math.floor(rounded / 60) % 24).padStart(2, '0');
      found.add(`${rh}:00`);
    }
    if (found.size > 0) delta.schedule_times = [...found].sort();
  }
}

// ── Timezone ──────────────────────────────────────────────────────────────
if ((m = msg.match(/(?:timezone|time zone|tz)\s*(?:to|=|:)?\s*([\w]+\/[\w_\/]+)/i))) {
  delta.timezone = m[1];
}

// ── Apply delta ──────────────────────────────────────────────────────────
for (const [key, val] of Object.entries(delta)) {
  if (JSON.stringify(prefs[key]) !== JSON.stringify(val)) {
    const old = prefs[key];
    prefs[key] = val;
    changes.push('• ' + key + ': ' + (old !== undefined ? JSON.stringify(old) + ' → ' : '') + JSON.stringify(val));
  }
}

if (!changes.length) {
  return [{ json: { message: "ℹ️ I didn\'t catch a clear preference there\\. Try:\n• \"I\'m in NYC\"\n• \"always remote only\"\n• \"min salary $150k\"\n• \"send me jobs at 9am and 6pm\" (rounded to 3-hour boundaries)\n• \"stop scheduled jobs\"" } }];
}

prefs._history = prefs._history || [];
prefs._history.push({ ts: new Date().toISOString(), delta });
if (prefs._history.length > 20) prefs._history = prefs._history.slice(-20);
prefs._updated_at = new Date().toISOString();

const firstKey = Object.keys(delta)[0];
return [{ json: { message: '✅ *Preferences updated:*\n' + changes.join('\n') + '\n\n_Reply \\`/prefs\\` to see all, \\`/prefs forget ' + firstKey + '\\` to remove\\._' } }];

// Handle Pref Forget
const msg   = $('Extract Input').first().json.message_text || '';
const match = msg.match(/forget\s+([a-z_]+)/i);
const key   = match?.[1]?.toLowerCase();
const sd    = $getWorkflowStaticData('global');
const prefs = sd.user_prefs || {};

if (key && prefs[key] !== undefined) {
  delete prefs[key];
  prefs._updated_at = new Date().toISOString();
  return [{ json: { message: '✅ Removed preference: *' + key + '*\n\n_Reply \\`/prefs\\` to see remaining preferences\\._' } }];
}

const available = Object.keys(prefs).filter(k => !k.startsWith('_'));
const listStr   = available.length ? available.join(', ') : '(none yet)';
return [{ json: { message: 'ℹ️ No preference named *' + (key || '?') + '* found\.\n\n_Available: ' + listStr + '_' } }];

// Toggle Verbose Mode
const msg = $('Extract Input').first().json.message_text || '';
const on  = /on|enable|yes|true/i.test(msg);
const sd  = $getWorkflowStaticData('global');
if (!sd.user_prefs) sd.user_prefs = {};
sd.user_prefs.verbose    = on;
sd.user_prefs._updated_at = new Date().toISOString();
const state  = on ? 'ON 🔔' : 'OFF 🔕';
const detail = on
  ? "I\'ll confirm what I understood before each search\\. Reply \"edit\" to refine\\."
  : "Searches will run silently\\. Send /verbose on anytime to re-enable\\.";
return [{ json: { message: `🔔 Verbose mode: *${state}*\n${detail}` } }];

// Schedule Gate
// Decides whether the current 3-hour tick fire matches a user-configured slot.
// Returns [] (silent short-circuit) if not.
//
// User prefs ($getWorkflowStaticData("global").user_prefs):
//   schedule_times: ["09:00", "18:00"]   (HH:MM 24h, 3-hour-aligned)
//                                         unset → use defaults
//                                         empty array → schedule disabled
//   timezone:       "America/New_York"   (IANA tz)
//
// Slots are rounded to the nearest 3-hour boundary (00, 03, 06, 09, 12, 15, 18, 21)
// so any user-stored time matches the tick fires correctly.
// 30-minute last-fire guard prevents accidental double-fires.

const sd = $getWorkflowStaticData("global");
const prefs = sd.user_prefs || {};

let slots;
if (prefs.schedule_times === undefined) {
  slots = ["09:00", "18:00"];
} else if (Array.isArray(prefs.schedule_times) && prefs.schedule_times.length === 0) {
  return [];
} else if (Array.isArray(prefs.schedule_times)) {
  slots = prefs.schedule_times;
} else {
  slots = ["09:00", "18:00"];
}

const tz = prefs.timezone || "America/New_York";

const fmt = new Intl.DateTimeFormat("en-US", {
  timeZone: tz, hour12: false, hour: "2-digit", minute: "2-digit"
});
const parts = Object.fromEntries(fmt.formatToParts(new Date()).map(p => [p.type, p.value]));
const nowHHMM = `${parts.hour}:${parts.minute}`;

// Round HH:MM to nearest 3-hour boundary (00, 03, 06, 09, 12, 15, 18, 21)
const round3h = (hhmm) => {
  const [h, m] = hhmm.split(":").map(Number);
  const totalMinutes = h * 60 + m;
  // 180 minutes = 3 hours
  const rounded = Math.round(totalMinutes / 180) * 180;
  const rh = String(Math.floor(rounded / 60) % 24).padStart(2, "0");
  return `${rh}:00`;
};

const nowSlot = round3h(nowHHMM);
const normalizedSlots = slots.map(round3h);
if (!normalizedSlots.includes(nowSlot)) return [];

// Last-fire guard: skip if same slot fired within last 30 minutes
sd._schedule_lastfire = sd._schedule_lastfire || {};
const lastFiredAt = sd._schedule_lastfire[nowSlot];
const nowMs = Date.now();
if (lastFiredAt && (nowMs - lastFiredAt) < 30 * 60 * 1000) return [];

sd._schedule_lastfire[nowSlot] = nowMs;
const cutoff = nowMs - 7 * 24 * 60 * 60 * 1000;
for (const k of Object.keys(sd._schedule_lastfire)) {
  if (sd._schedule_lastfire[k] < cutoff) delete sd._schedule_lastfire[k];
}

return [{ json: { _slot: nowSlot, _tz: tz, _scheduled: true } }];

// Prep Expand Input
// Route Intent strips message_text from $json — this restores it
// from Extract Input (which always ran upstream in the Telegram path).
// Also injects user_prefs_snapshot so Expand Query's prompt is a
// simple $json reference (no cross-node expressions needed).

const sd = $getWorkflowStaticData('global');
const prefs = sd.user_prefs || {};

// Extract Input is guaranteed to have run in this execution path
let msg = 'find jobs';
try { msg = $('Extract Input').first().json.message_text || msg; } catch(e) {}

return [{
  json: {
    ...$input.first().json,         // carry through intent/entities from Route Intent
    message_text: msg,
    user_prefs_snapshot: JSON.stringify(prefs)
  }
}];

// Build Telegraph Body — pure data transformation, no HTTP calls
// Outputs all fields needed for the Telegraph CreatePage HTTP node
// and the final digest message assembly.

const sd = $getWorkflowStaticData('global');
const scored = $('Parse Scorer Output').first().json.scored || [];
const allJobs = $('Aggregate Jobs').first().json.jobs || [];
const intent = sd.last_search_intent || {};

const jobMap = {};
for (const j of allJobs) jobMap[j.job_id] = j;

const rankedJobs = scored
  .map(s => ({ ...jobMap[s.job_id], fit_score: s.fit_score, one_liner: s.one_liner }))
  .filter(j => j && j.url)
  .slice(0, 40);

// Build search context badges
const badges = [];
if (intent.location_canonical) badges.push('📍 ' + intent.location_canonical.split(',')[0]);
if (intent.salary_signals?.length) badges.push('💰 ' + intent.salary_signals[0]);
if (intent.visa_signals?.length) badges.push('🛂 ' + intent.visa_signals[0]);
if (intent.industry_signals?.length) badges.push('🏭 ' + intent.industry_signals[0]);
if (intent.seniority && intent.seniority !== 'any') badges.push('📊 ' + intent.seniority);
if (intent.remote_preference === 'remote_only') badges.push('🌍 Remote only');

const searchContext = (intent.role_families?.slice(0,3).join(', ') || 'Jobs')
  + (badges.length ? ' · ' + badges.join(' · ') : '')
  + ' · ' + rankedJobs.length + ' results';

function scoreEmoji(s) { return s >= 8 ? '🟢' : s >= 6 ? '🟡' : '⚪'; }
function clean(slug) { return (slug || '').replace(/-/g,' ').replace(/\b\w/g, l => l.toUpperCase()); }

// Build Telegraph content nodes
const contentNodes = [
  { tag: 'p', children: [{ tag: 'i', children: [searchContext] }] },
  { tag: 'p', children: ['Reply with a number in Telegram to generate a tailored resume + cover letter.'] },
  { tag: 'hr' }
];

const providers = new Set();
for (const j of rankedJobs) if (j.source) providers.add(j.source);
if (providers.size > 0) {
  const labels = { firecrawl: '🔥 Firecrawl', youcom: '🔍 You.com', serper: '⚡ Serper' };
  contentNodes.push({ tag: 'p', children: [{ tag: 'i', children: ['Powered by: ' + [...providers].map(p => labels[p] || p).join(' · ')] }] });
  contentNodes.push({ tag: 'hr' });
}

for (const [i, job] of rankedJobs.entries()) {
  const score = job.fit_score || 0;
  const posted = job.updated_at ? new Date(job.updated_at).toLocaleDateString('en-US', {month:'short',day:'numeric'}) : '';
  contentNodes.push({
    tag: 'h4',
    children: [
      (i + 1) + '. ' + scoreEmoji(score) + ' ',
      { tag: 'a', attrs: { href: job.url }, children: [job.title || 'Unknown Role'] }
    ]
  });
  const metaParts = [clean(job.company) || 'Unknown', job.location || 'Location N/A', score + '/10'];
  if (posted) metaParts.push(posted);
  contentNodes.push({ tag: 'p', children: [{ tag: 'i', children: [metaParts.join(' · ')] }] });
  if (job.one_liner) contentNodes.push({ tag: 'blockquote', children: [job.one_liner] });
}

// Build top-3 inline Telegram message (without telegraph URL — added later)
const top3 = rankedJobs.slice(0, 3);
let top3Msg = '🎯 *Found ' + rankedJobs.length + ' roles*\n';
if (badges.length) top3Msg += badges.join(' · ') + '\n';
top3Msg += '\n';
for (const [i, job] of top3.entries()) {
  const titleClean = (job.title || 'Unknown').replace(/[\[\]]/g, '');
  top3Msg += '*' + (i+1) + '.* [' + titleClean + '](' + job.url + ')\n';
  top3Msg += '    🏢 ' + clean(job.company) + ' · 📍 ' + (job.location || 'N/A') + '\n';
  top3Msg += '    📊 ' + (job.fit_score || 0) + '/10 — ' + (job.one_liner || '') + '\n\n';
}

// Auto-provision Telegraph token via fetch on first run, store in staticData
// This DOES use fetch but only once per workflow lifetime
let token = sd.telegraph_token;
if (!token) {
  try {
    const r = await fetch('https://api.telegra.ph/createAccount?short_name=CareerForge&author_name=CareerForge');
    const rj = await r.json();
    if (rj.ok) {
      token = rj.result.access_token;
      sd.telegraph_token = token;
    }
  } catch(e) {
    // Fall through; token will be empty and HTTP node will fail gracefully
  }
}

// Compose page title
const pageTitle = 'CareerForge — ' + rankedJobs.length + ' Jobs · ' +
  new Date().toLocaleDateString('en-US',{month:'short',day:'numeric'});

return [{
  json: {
    // For Telegraph CreatePage HTTP node
    access_token: token || '',
    title: pageTitle,
    author_name: 'CareerForge',
    content: JSON.stringify(contentNodes),
    return_content: 'false',

    // For Assemble Digest
    top3_msg: top3Msg,
    total_jobs: rankedJobs.length,
    badges,
    rankedJobs,
    has_token: Boolean(token)
  }
}];

// Assemble Digest — combines Telegraph URL with top3 message
// Reads from Build Telegraph Body for top3_msg/rankedJobs and from
// the previous HTTP node ($input) for the Telegraph response.

const buildData = $('Build Telegraph Body').first().json;
const sd = $getWorkflowStaticData('global');

const top3Msg = buildData.top3_msg;
const rankedJobs = buildData.rankedJobs;
const totalJobs = buildData.total_jobs;

// Try to extract Telegraph URL from HTTP response
let telegraphUrl = null;
try {
  const httpResp = $input.first().json;
  if (httpResp.ok && httpResp.result && httpResp.result.url) {
    telegraphUrl = httpResp.result.url;
  }
} catch(e) {}

// Build final message
let msg = top3Msg;
if (telegraphUrl) {
  msg += '📋 *Full list (' + totalJobs + ' jobs):*\n' + telegraphUrl + '\n\n';
} else {
  msg += '_(Telegraph page unavailable — top 3 shown above)_\n\n';
}
msg += '_Reply with a number (1–' + Math.min(totalJobs, 40) + ') to apply._';

// Store in staticData for apply flow
const last_jobs = {};
rankedJobs.slice(0, 40).forEach((job, i) => {
  last_jobs[i+1] = {
    job_id: job.job_id, title: job.title, company: job.company,
    location: job.location, url: job.url, fit_score: job.fit_score,
    description_snippet: job.description_snippet || ''
  };
});
sd.last_jobs = last_jobs;

return [{ json: { message: msg, telegraph_url: telegraphUrl, total_jobs: totalJobs } }];
